import assert from 'node:assert/strict';
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { parseManifest } from './packages/core/src/domain/manifest.ts';
import { buildSkillPackage } from './packages/core/src/domain/skill-package.ts';
import { validatePackage } from './packages/core/src/application/validate-package.ts';
const root = path.resolve('skills/gof-command');
function gather(dir, prefix = '') {
  return readdirSync(dir, { withFileTypes: true }).flatMap(e => {
    const rel = prefix + e.name;
    return e.isDirectory() ? gather(path.join(dir, e.name), rel + '/') : [{ path: rel, bytes: readFileSync(path.join(dir, e.name)) }];
  });
}
const files = gather(root);
const parsed = parseManifest(readFileSync(path.join(root, 'skill.yaml'), 'utf8'));
const pkg = buildSkillPackage(parsed.manifest, files);
const report = validatePackage(pkg, { directoryName: 'gof-command' });
assert.deepEqual(parsed.issues, []);
assert.deepEqual(report.issues, []);
assert.equal(parsed.manifest.version, '1.2.5');
let linkCount = 0;
for (const file of files.filter(f => f.path.endsWith('.md'))) {
  const text = file.bytes.toString('utf8');
  for (const match of text.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)) {
    const href = match[1];
    if (/^(?:https?:|mailto:)/.test(href)) continue;
    const [relative, fragment] = href.split('#');
    const target = path.resolve(root, path.dirname(file.path), relative || path.basename(file.path));
    assert.ok(target.startsWith(root + path.sep), href);
    assert.ok(existsSync(target), href);
    if (fragment) {
      const headings = [...readFileSync(target, 'utf8').matchAll(/^#+\s+(.+)$/gm)].map(m => m[1].toLowerCase().replace(/[^\w\s-]/g, '').trim().replace(/\s+/g, '-'));
      assert.ok(headings.includes(fragment), href);
    }
    linkCount++;
  }
}
const entry = readFileSync(path.join(root, 'SKILL.md'), 'utf8');
for (const file of files.filter(f => f.path.startsWith('references/'))) assert.ok(entry.includes(file.path), 'Unrouted reference: ' + file.path);
console.log(JSON.stringify({ name: parsed.manifest.name, version: parsed.manifest.version, files: files.length, packageIssues: report.issues, manifestIssues: parsed.issues, relativeLinksChecked: linkCount, referencesRouted: files.filter(f => f.path.startsWith('references/')).length }));
